INSERT INTO `user` VALUES (1,'admin','admin@test.com',NULL,'https://avatars.githubusercontent.com/u/159103134?v=4','动态规划状态转移方程背得滚瓜烂熟，一写代码发现边界条件全崩；双指针思路门儿清，跑起来指针飞出场外；回溯剪枝理论满分，实际递归栈溢出直接裂开。KMP next数组推导了三页草稿纸，真到匹配时i和j双双迷路；单调栈原理倒背如流，遇到下一个更大元素当场卡死。拓扑排序画图一气呵成，建图时邻接表漏了一半节点。',6,104,'lmliheng','Beijing','8d969eef6ecad3c29a3a629280e686cf0c3f5d5a86aff3ca12020c923adc6c92','2026-05-08 18:38:40','2026-08-25 06:02:46',1),(2,'editor','editor@test.com',NULL,'https://avatars.githubusercontent.com/u/159103134?v=4',NULL,0,0,NULL,NULL,'8d969eef6ecad3c29a3a629280e686cf0c3f5d5a86aff3ca12020c923adc6c92','2026-05-08 18:38:40','2026-05-09 01:02:16',3),(3,'user1','user1@test.com',NULL,'https://avatars.githubusercontent.com/u/159103134?v=4','????',8,0,NULL,'????','13484b1c3b62da1e5087466a23abcd83febb04d83731642e09693ec3e312c692','2026-05-08 18:38:40','2026-08-25 03:10:59',2),(1778237621052,'liheng2','liheng@112',NULL,'https://tse2.mm.bing.net/th/id/OIP.67yhbZpufXNcxzTdRR_fmwHaHa?r=0&cb=thfvnextfalcon&rs=1&pid=ImgDetMain&o=7&rm=3','算法训练家',2,42,'小恒','北京','13484b1c3b62da1e5087466a23abcd83febb04d83731642e09693ec3e312c692','2026-05-08 18:53:41','2026-05-29 18:33:55',2),(1778237621054,'testuser_0001','testuser_0001@example.com',NULL,NULL,NULL,0,0,NULL,NULL,'8d969eef6ecad3c29a3a629280e686cf0c3f5d5a86aff3ca12020c923adc6c92','2026-08-25 02:42:46','2026-08-25 02:42:46',2),(1778237621055,'testuser_0002','testuser_0002@example.com',NULL,NULL,NULL,0,0,NULL,NULL,'8d969eef6ecad3c29a3a629280e686cf0c3f5d5a86aff3ca12020c923adc6c92','2026-08-25 02:42:46','2026-08-25 02:42:46',2),(1778237621056,'testuser_0003','testuser_0003@example.com',NULL,NULL,NULL,0,0,NULL,NULL,'8d969eef6ecad3c29a3a629280e686cf0c3f5d5a86aff3ca12020c923adc6c92','2026-08-25 02:42:46','2026-08-25 02:42:46',2),(1778237621057,'testuser_0004','testuser_0004@example.com',NULL,NULL,NULL,0,0,NULL,NULL,'8d969eef6ecad3c29a3a629280e686cf0c3f5d5a86aff3ca12020c923adc6c92','2026-08-25 02:42:46','2026-08-25 02:42:46',2),(1778237621058,'testuser_0005','testus